// src/theme/tcw.css from src/theme/tcw-tokens.json: the design system of The Cyborg Way (TCW-1 fase 5).
// Dark on :root (the default), every colour again under [data-theme='light']. This generated file is the only
// place in the app where a colour is written as a value; src/test/brand.test.ts checks it.
//   node scripts/build-tokens.mjs           writes the file
//   node scripts/build-tokens.mjs --check   fails if it is out of date
import { readFileSync, writeFileSync } from 'node:fs';

const tokens = JSON.parse(readFileSync('src/theme/tcw-tokens.json', 'utf8'));
const themed = [...tokens.color.tokens, ...tokens.shadow.tokens, ...tokens.categorical.tokens];
const line = (name, value) => `  --${name}: ${value};`;
const rest = ['spacing', 'radius', 'duration'].flatMap((k) => tokens[k].tokens.map((t) => line(`tcw-${t.name}`, t.value)));
const css = [
  '/* The Cyborg Way tokens. Generated by scripts/build-tokens.mjs from src/theme/tcw-tokens.json: do not edit. */',
  ':root {', '  color-scheme: dark;',
  ...themed.map((t) => line(t.name, t.value.dark)),
  ...Object.entries(tokens.type.families).map(([name, value]) => line(`tcw-font-${name}`, value)),
  ...rest, '}',
  ":root[data-theme='light'] {", '  color-scheme: light;',
  ...themed.map((t) => line(t.name, t.value.light)), '}', '',
].join('\n');

if (process.argv.includes('--check')) {
  const same = readFileSync('src/theme/tcw.css', 'utf8') === css;
  console.log(same ? 'tcw.css matches tcw-tokens.json' : 'tcw.css is out of date: node scripts/build-tokens.mjs');
  process.exit(same ? 0 : 1);
}
writeFileSync('src/theme/tcw.css', css);
console.log('wrote src/theme/tcw.css');
